#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const ll mod = 1000000007;

#define IOS ios::sync_with_stdio(0); cin.tie(0);
#define endl "\n"

ll dp[55][55][3];
ll c[55][55];

signed main() {
    IOS;

    dp[0][0][1] = 1;
    dp[1][0][1] = 0;
    dp[1][0][0] = 1;
    dp[0][0][0] = 1;

    int n, k;
    cin >> n >> k;

    c[0][0] = 1;
    for (int i = 1; i <= n; c[i][0] = 1, i++)
        for (int j = 1; j <= n; j++)
            c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;

    for (int i = 2; i <= n; i++) {
        for (int j = 0; j <= k; j++) {
            for (int Left = 1; Left <= i - 1; Left++) {
                ll coef = c[i - 2][Left - 1] * Left
                          * max(1, i - Left - 1) % mod;

                for (int kLeft = 0; kLeft <= j - 1; kLeft++) {
                    ll addFi =
                        dp[Left][kLeft][0] *
                        ((i - Left - 1) > 0
                             ? dp[i - Left - 1][j - 1 - kLeft][1] +
                                   dp[i - Left - 1][j - 1 - kLeft][0]
                             : j - kLeft - 1 == 0 ? 1 : 0);

                    ll addSe =
                        ((i - Left - 1) > 0
                             ? dp[Left][kLeft][1] *
                                   dp[i - Left - 1][j - 1 - kLeft][0]
                             : 0);

                    dp[i][j][1] =
                        (dp[i][j][1] + coef * ((addFi + addSe) % mod)) % mod;
                }

                for (int kLeft = 0; kLeft <= j; kLeft++) {
                    dp[i][j][0] +=
                        coef * dp[Left][kLeft][1] % mod *
                        dp[i - Left - 1][j - kLeft][1] % mod;
                    dp[i][j][0] %= mod;
                }
            }
        }
    }

    cout << (dp[n][k][0] + dp[n][k][1]) % mod;
}

